def create_catalog(apps, schema_editor):
    """Catálogo de permissões e perfis de exemplo, que são dados comuns e não recebem PERFIL.*, CONFIGURACAO.EDITAR nem o alcance acadêmico."""
    Permission = apps.get_model('accounts', 'Permission')
    Role = apps.get_model('accounts', 'Role')
    RolePermission = apps.get_model('accounts', 'RolePermission')
    for code, description in PERMISSIONS:
        Permission.objects.create(code=code, description=description)
    for code, name in INITIAL_ROLES:
        role = Role.objects.create(code=code, name=name)
        RolePermission.objects.bulk_create(
            RolePermission(role=role, permission=permission)
            for permission in Permission.objects.filter(code__in=INITIAL_GRANTS[code])
        )

